class InsufficientInventoryError extends Error {}

async function placeOrder(customerId: string, productId: string, quantity: number) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');

    // Step 1: check and decrement inventory, all within the transaction
    const inventoryResult = await client.query(
      'UPDATE inventory SET quantity = quantity - $1 WHERE product_id = $2 AND quantity >= $1 RETURNING quantity',
      [quantity, productId]
    );

    if (inventoryResult.rowCount === 0) {
      // The WHERE clause's quantity >= $1 prevented the update from
      // matching anything if stock was insufficient - this check,
      // exactly Module 7's explicit-result-verification discipline,
      // is what detects that failure
      throw new InsufficientInventoryError('Not enough stock');
    }

    // Step 2: create the order record, still within the SAME transaction
    const orderResult = await client.query(
      'INSERT INTO orders (customer_id, product_id, quantity) VALUES ($1, $2, $3) RETURNING id',
      [customerId, productId, quantity]
    );

    await client.query('COMMIT'); // BOTH the inventory decrement AND
                                     // the order creation are now permanent
    return orderResult.rows[0];
  } catch (err) {
    await client.query('ROLLBACK'); // if EITHER step failed, BOTH are undone
    throw err;
  } finally {
    client.release();
  }
}

codingChallenge.starterCode:
class InsufficientFundsError extends Error {}

// TODO: build transferFunds(fromId, toId, amount) using BEGIN/COMMIT/ROLLBACK,
// checking the debit's affected row count to detect insufficient funds
// (the UPDATE's WHERE clause should require balance >= amount),
// throwing InsufficientFundsError and rolling back if so

codingChallenge.solutionExample:
class InsufficientFundsError extends Error {}

async function transferFunds(fromId: string, toId: string, amount: number) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');

    const debitResult = await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2 AND balance >= $1 RETURNING balance',
      [amount, fromId]
    );

    if (debitResult.rowCount === 0) {
      throw new InsufficientFundsError('Insufficient funds for transfer');
    }

    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId]
    );

    await client.query('COMMIT');
    return { success: true };
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

sections.content:
PostgreSQL's EXPLAIN ANALYZE, showing the genuine execution plan and actual timing:

EXPLAIN ANALYZE
SELECT * FROM orders WHERE customer_id = 42;
-- Output might show: "Seq Scan on orders (actual time=0.05..15.20 rows=3)"
-- 'Seq Scan' means every row was checked - genuinely slow at scale

After creating an index:

CREATE INDEX idx_orders_customer_id ON orders (customer_id);

EXPLAIN ANALYZE
SELECT * FROM orders WHERE customer_id = 42;
-- Output now shows: "Index Scan using idx_orders_customer_id
-- (actual time=0.01..0.03 rows=3)" - dramatically faster,
-- genuinely confirmed by the actual measured timing

MongoDB's .explain(), showing the equivalent information:

db.orders.find({ customerId: 42 }).explain('executionStats');
// Look for executionStats.totalDocsExamined versus nReturned -
// if totalDocsExamined is far larger than nReturned, every document
// is being scanned despite few actually matching - a strong signal
// an index is genuinely needed

db.orders.createIndex({ customerId: 1 });

